102		@Override
103		public void render(RenderRequest renderRequest, RenderResponse renderResponse) throws IOException, PortletException {
104			
105			ThemeDisplay themeDisplay = (ThemeDisplay) renderRequest.getAttribute(WebKeys.THEME_DISPLAY);
106	
107			MessageUtility messageUtility = new MessageUtility(ScrivaniaCittadinoPortletKeys.BUNDLE_SYMBOLIC_NAME, themeDisplay.getSiteDefaultLocale());
108	
109			String tabAttivaValue = ParamUtil.getString(renderRequest, ScrivaniaCittadinoPortletKeys.TAB_ATTIVA);
110			List<TipologiaComunicazione> listaTipologiaComunicazione = new ArrayList<TipologiaComunicazione>();
111			List<Tipologia> listaTipologiaServizi = new ArrayList<Tipologia>();
112			try {
113				listaTipologiaComunicazione = tipologiaComunicazioneLocalService.getTipologiaComunicaziones(QueryUtil.ALL_POS, QueryUtil.ALL_POS);
114				listaTipologiaServizi = tipologiaLocalService.getTipologias(QueryUtil.ALL_POS, QueryUtil.ALL_POS);
115			}
116			catch (Exception e) {
117				auditService.saveErrorLog(renderRequest, e.getMessage());
118				_log.error("render :: " + e.getMessage(), e);
119			}
120	
121			try {
122				User loggedUser = themeDisplay.getUser();
123				ComunicazioneFilters comunicazioneFilters = new ComunicazioneFilters();
124				comunicazioneFilters.setGroupId(themeDisplay.getScopeGroupId());
125				comunicazioneFilters.setCompanyId(themeDisplay.getCompanyId());
126				comunicazioneFilters.setUsername(loggedUser.getScreenName());
127				
128				long totaleMessaggiNonletti = scrivaniaCittadinoMiddlewareService.getNumTotaleComunicazioni(loggedUser.getUserId(), themeDisplay.getScopeGroupId(), themeDisplay.getCompanyId(), loggedUser.getScreenName());
129	
130				List<String> tabsValues = new ArrayList<>(
131						Arrays.asList(ScrivaniaCittadinoPortletKeys.SEZIONE_APPUTAMENTI,
132								ScrivaniaCittadinoPortletKeys.SEZIONE_ATTIVITA,
133								ScrivaniaCittadinoPortletKeys.SEZIONE_PAGAMENTI,
134								ScrivaniaCittadinoPortletKeys.SEZIONE_DOMANDE_BANDO,
135								ScrivaniaCittadinoPortletKeys.SEZIONE_RICHIESTE_REFERENTE,
136								ScrivaniaCittadinoPortletKeys.DETTAGLIO_MESSAGGI,
137								ScrivaniaCittadinoPortletKeys.SEZIONE_SERVIZI
138						));
139	
140				ServiziDigitaliCommonConfiguration serviziDigitaliConfiguration = configurationProvider.getGroupConfiguration(ServiziDigitaliCommonConfiguration.class, themeDisplay.getScopeGroupId());
141				boolean bandiEnabled = serviziDigitaliConfiguration.bandiEnabled();
142				boolean pagamentiEnabled = serviziDigitaliConfiguration.pagamentiEnabled();
143				if (!bandiEnabled) {
144					tabsValues.remove(ScrivaniaCittadinoPortletKeys.SEZIONE_DOMANDE_BANDO);
145				}
146				
147				if (!pagamentiEnabled) {
148					tabsValues.remove(ScrivaniaCittadinoPortletKeys.SEZIONE_PAGAMENTI);
149				}
150	
151				/**
152				 * Verifica e gestisce
153				 * la presenza di servizi dinamici aggiuntivi
154				 * da visualizzare sulla scrivania del cittadino.
155				 */
156				if(serviziDigitaliConfiguration.abilitaServiziDinamiciAggiuntivi()) {
157					try {
158						ObjectMapper om = new ObjectMapper();
159						TypeReference<List<ServizioAggiuntivoConfig>> t = new TypeReference<List<ServizioAggiuntivoConfig>>() {};
160						List<ServizioAggiuntivoConfig> serviziAggiuntivi  = om.readValue(serviziDigitaliConfiguration.serviziDinamiciAggiuntiviJson(), t);
161	
162						for (ServizioAggiuntivoConfig s : serviziAggiuntivi) {
163							if(s.isAbilitato()){
164								tabsValues.add(s.getLabelServizio());
165							}
166						}
167	
168						renderRequest.setAttribute(ScrivaniaCittadinoPortletKeys.SERVIZI_DINAMICI_AGGIUNTIVI_CONFIGS,
169								serviziAggiuntivi);
170	
171					}catch (Exception e) {
172						_log.error("Errori nel parsing dei tab dinamici", e);
173					}
174				}
175	
176				String tabsValuesCommaSeparated = String.join(",", tabsValues);
177	
178				renderRequest.setAttribute(ScrivaniaCittadinoPortletKeys.TABS_VALUES, tabsValuesCommaSeparated);
179				renderRequest.setAttribute(ScrivaniaCittadinoPortletKeys.BANDI_ENABLED, bandiEnabled);
180				renderRequest.setAttribute(ScrivaniaCittadinoPortletKeys.PAGAMENTI_ENABLED, pagamentiEnabled);
181				renderRequest.setAttribute(ScrivaniaCittadinoPortletKeys.NUMERO_MESSAGGI_NON_LETTI, totaleMessaggiNonletti);
182				renderRequest.setAttribute(ScrivaniaCittadinoPortletKeys.SERVIZI_DINAMICI_AGGIUNTIVI_ABILITATI,
183						serviziDigitaliConfiguration.abilitaServiziDinamiciAggiuntivi());
184			}
185			catch (ConfigurationException e) {
186				_log.error("render :: " + e.getMessage(), e);
187			}
188	
189			renderRequest.setAttribute(ScrivaniaCittadinoPortletKeys.LISTA_TIPOLOGIA_COMUNICAZIONE, listaTipologiaComunicazione);
190			renderRequest.setAttribute(ScrivaniaCittadinoPortletKeys.LISTA_STATO, Arrays.asList(StatoRichiesta.values()));
191			renderRequest.setAttribute(ScrivaniaCittadinoPortletKeys.LISTA_STATO_RICHIESTA_REFERENTE, Arrays.asList(it.servizidigitali.gestione.referente.istanze.common.enumeration.StatoRichiesta.values()));
192			renderRequest.setAttribute(ScrivaniaCittadinoPortletKeys.LISTA_TIPOLOGIA_RICHIESTA, listaTipologiaServizi);
193			renderRequest.setAttribute(ScrivaniaCittadinoPortletKeys.TAB_ATTIVA, tabAttivaValue);
194	
195			super.render(renderRequest, renderResponse);
196		}
197	
198	}

