import org.osgi.service.component.annotations.Reference;

import it.servizidigitali.catalogoservizi.frontend.configuration.CatalogoServiziEnteConfiguration;
import it.servizidigitali.common.utility.enumeration.FriendlyUrl;
import it.servizidigitali.gestioneenti.model.ServizioEnte;
import it.servizidigitali.gestioneenti.service.ServizioEnteLocalService;
import it.servizidigitali.gestioneservizi.model.Servizio;
import it.servizidigitali.gestioneservizi.service.ServizioLocalService;

@Component(name = "catalogoServiziMiddlewareService", immediate = true, service = CatalogoServiziMiddlewareService.class)
public class CatalogoServiziMiddlewareService {

	private ConfigurationProvider configurationProvider;

	@Reference
	protected void setConfigurationProvider(ConfigurationProvider configurationProvider) {
		this.configurationProvider = configurationProvider;
	}

	@Reference
	private ServizioLocalService servizioLocalService;

	@Reference
	private ServizioEnteLocalService servizioEnteLocalService;

	public List<Servizio> getServizioByParams(String nome, List<Long> areaTematicaId, List<Long> tipologiaId, long companyId, long groupId, long organizationId, int cur,
			int delta, String orderByCol, String orderByType) throws Exception {

		List<ServizioEnte> listaIdServiziEnteDisponibili = servizioEnteLocalService.getServiziEnteByCompanyOrganization(companyId, organizationId);

		listaIdServiziEnteDisponibili = checkListaServiziEnte(listaIdServiziEnteDisponibili);

		List<Long> serviziId = listaIdServiziEnteDisponibili.stream().map(ServizioEnte::getServizioId).collect(Collectors.toList());
		List<Servizio> listaServizi = servizioLocalService.getServiziUtilizzabili(serviziId, nome, areaTematicaId, tipologiaId, null, cur, delta, orderByCol, orderByType);

		listaServizi = checkListaServizi(listaServizi);

		return completaListaServizi(listaServizi, listaIdServiziEnteDisponibili);

		// return listaServizi;

	}

	/**
	 * @param listaServizi
	 */
	private List<Servizio> checkListaServizi(List<Servizio> listaServizi) {
		if (listaServizi != null) {
			for (Servizio servizio : listaServizi) {
				servizio = checkServizio(servizio);
			}
			return listaServizi;
		}
		return null;
	}

	private List<ServizioEnte> checkListaServiziEnte(List<ServizioEnte> listaServiziEnte) {
		if (listaServiziEnte != null) {
			for (ServizioEnte servizioEnte : listaServiziEnte) {
				servizioEnte = checkServizioEnte(servizioEnte);
			}
			return listaServiziEnte;
		}
		return null;
	}

	public Servizio checkServizio(Servizio servizio) {
		if (Validator.isNotNull(servizio)) {	
				// Controllo accesso a servizio per data attivazione
				Date dataInizioAttivazione = servizio.getDataInizioAttivazione();
				Date dataFineAttivazione = servizio.getDataFineAttivazione();

				if (dataInizioAttivazione != null && dataFineAttivazione != null) {
					Date now = new Date();
					if (!(now.compareTo(dataInizioAttivazione) >= 0 && now.compareTo(dataFineAttivazione) <= 0)) {
						servizio.setAttivo(false);
					}		
			}
			return servizio;
		}
		return null;
	}

	public ServizioEnte checkServizioEnte(ServizioEnte servizioEnte) {
		if (Validator.isNotNull(servizioEnte)) {		
				// Controllo accesso a servizio per data attivazione
				Date dataInizioAttivazione = servizioEnte.getDataInizioAttivazione();
				Date dataFineAttivazione = servizioEnte.getDataFineAttivazione();

				if (dataInizioAttivazione != null && dataFineAttivazione != null) {
					Date now = new Date();
					if (!(now.compareTo(dataInizioAttivazione) >= 0 && now.compareTo(dataFineAttivazione) <= 0)) {
						servizioEnte.setAttivo(false);
					}
				}
			return servizioEnte;
		}
		return null;
	}

	/**
	 *
	 * @param servizioId
	 * @param groupId
	 * @return
	 * @throws ConfigurationException
	 */
	public String getSchedaServizioCatalogo(long servizioId, long groupId) throws ConfigurationException {

		CatalogoServiziEnteConfiguration catalogoServiziEnteConfiguration = configurationProvider.getGroupConfiguration(CatalogoServiziEnteConfiguration.class, groupId);

		String pagePath = catalogoServiziEnteConfiguration.pagePath();

		return pagePath += "/-/" + FriendlyUrl.SCHEDA_SERVIZIO.getMapping() + "/" + servizioId;
	}

	private List<Servizio> completaListaServizi(List<Servizio> servizi, List<ServizioEnte> serviziEnte) {

		for(Servizio s: servizi) {

			Optional<ServizioEnte> optSe = serviziEnte.stream().
					filter(se -> Long.compare(se.getServizioId(), s.getServizioId()) == 0).
					findFirst();
			if(optSe.isPresent()) {
				ServizioEnte se = optSe.get();
				s.setLinkEsterno(se.getUriEsterna());

				if(Long.compare(se.getCatalogoServizioArticleId(), 0L) != 0) {
					s.setHasSchedaServizio(true);
				}

			}
		}

		return servizi;
	}

}

