import javax.portlet.Portlet;
import javax.portlet.PortletException;
import javax.portlet.RenderRequest;
import javax.portlet.RenderResponse;

import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Reference;

import it.servizidigitali.audit.common.service.AuditService;
import it.servizidigitali.catalogoservizi.frontend.constants.CatalogoServiziPortletKeys;
import it.servizidigitali.catalogoservizi.frontend.service.CatalogoServiziMiddlewareService;
import it.servizidigitali.common.utility.OrganizationUtility;
import it.servizidigitali.common.utility.ServletParamUtil;
import it.servizidigitali.common.utility.UrlUtility;
import it.servizidigitali.gestioneservizi.model.Servizio;

/**
 * @author pindi
 */
@Component(//
		immediate = true, //
		property = { //
				"com.liferay.portlet.display-category=category.servizidigitali", //
				"com.liferay.portlet.header-portlet-css=/css/main.css", //
				"com.liferay.portlet.instanceable=false", //
				"javax.portlet.display-name=CatalogoServizi", //
				"javax.portlet.init-param.template-path=/", //
				"javax.portlet.init-param.view-template=/view.jsp", //
				"javax.portlet.name=" + CatalogoServiziPortletKeys.CATALOGOSERVIZI, //
				"javax.portlet.resource-bundle=content.Language", //
				"javax.portlet.security-role-ref=power-user,user"//
		}, //
		service = Portlet.class//
) //
public class CatalogoServiziPortlet extends MVCPortlet {

	private static final Log _log = LogFactoryUtil.getLog(CatalogoServiziPortlet.class);

	@Reference
	private CatalogoServiziMiddlewareService catalogoServiziMiddlewareService;

	@Reference
	private OrganizationUtility organizationUtility;

	@Reference
	private AuditService auditService;

	@Override
	public void render(RenderRequest renderRequest, RenderResponse renderResponse) throws IOException, PortletException {
		String queryNome = ParamUtil.getString(renderRequest, "queryNome");
		List<Long> queryArea = ServletParamUtil.getParameterValues(renderRequest, CatalogoServiziPortletKeys.PARAM_AREA);
		List<Long> queryTipologia = ServletParamUtil.getParameterValues(renderRequest, CatalogoServiziPortletKeys.PARAM_TIPOLOGIA);

		ServiceContext serviceContext = null;
		ThemeDisplay themeDisplay = null;
		List<Servizio> listaServizi = new ArrayList<Servizio>();
		String nomeEnte = "";
		long companyId = 0L;
		long groupId = 0L;

		try {
			serviceContext = ServiceContextFactory.getInstance(renderRequest);
			themeDisplay = serviceContext.getThemeDisplay();
			groupId = themeDisplay.getScopeGroupId();
			Organization siteOrganization = organizationUtility.getSiteOrganization(themeDisplay.getScopeGroupId());
			nomeEnte = siteOrganization.getName();
			listaServizi = catalogoServiziMiddlewareService.getServizioByParams(queryNome, queryArea, queryTipologia, companyId, groupId, siteOrganization.getOrganizationId(), 0, 0, null, null);
			if (Validator.isNull(listaServizi) || listaServizi.isEmpty()) {
				renderRequest.setAttribute(CatalogoServiziPortletKeys.NOME_ENTE, siteOrganization.getName());
			}
		}
		catch (Exception e) {
			auditService.saveErrorLog(renderRequest, e.getMessage());
			_log.error("Impossibile ottenere la lista di servizi :: " + e.getMessage(), e);
		}

		String urlPart = UrlUtility.generateUrlPart(CatalogoServiziPortletKeys.PARAM_AREA, queryArea) + UrlUtility.generateUrlPart(CatalogoServiziPortletKeys.PARAM_TIPOLOGIA, queryTipologia);
		renderRequest.setAttribute("urlPart", urlPart);
		renderRequest.setAttribute(CatalogoServiziPortletKeys.LISTA_SERVIZI, listaServizi);
		renderRequest.setAttribute(CatalogoServiziPortletKeys.NOME_ENTE, nomeEnte);
		super.render(renderRequest, renderResponse);
	}

}

