96			TipologiaComunicazione tipologiaComunicazione = TipologiaComunicazione.getByKey(tipologiaComunicazioneString);
97	
98			ThemeDisplay themeDisplay = (ThemeDisplay) renderRequest.getAttribute(WebKeys.THEME_DISPLAY);
99	
100			int[] limits = SearchPaginationUtil.calculateStartAndEnd(cur, delta);
101			int start = limits[0];
102			int end = limits[1];
103	
104			ComunicazioneDto dto = getDettaglioComunicazione(comunicazioneId, 
105					tipologiaComunicazione, 
106					start, end, 
107					themeDisplay.getCompanyId(), 
108					themeDisplay.getScopeGroupId(), 
109					themeDisplay.getSiteDefaultLocale(),
110					themeDisplay.getUserId());
111	
112			renderRequest.setAttribute("comunicazione", dto);
113			renderRequest.setAttribute(ScrivaniaCittadinoPortletKeys.PARAM_LIST_CUR, listCur);
114	
115			switch (tipologiaComunicazione){
116				case COMUNICAZIONE:
117					if (dto.getSubOrganizationId() > 0) {
118		        		long[] organizationIds = userLocalService.getOrganizationUserIds(dto.getSubOrganizationId());
119		        		letturaMessaggioLocalService.setMessaggiLetti(comunicazioneId, themeDisplay.getUserId(), organizationIds);
120					} else {
121						letturaMessaggioLocalService.setMessaggiLetti(comunicazioneId, themeDisplay.getUserId());
122					}
123					break;
124				case COMMENTO_DOMANDA_BANDO:
125					scrivaniaCittadinoMiddlewareService.setLetturaCommentoDomandaBando(comunicazioneId);
126					break;
127				case COMMENTO_RICHIESTA_SERVIZIO:
128					scrivaniaCittadinoMiddlewareService.setLetturaCommentoRichiesta(comunicazioneId);
129					break;
130				default:
