138		private ComunicazioneDto getDettaglioComunicazione(long comunicazioneId, TipologiaComunicazione tipologiaComunicazione, int start, int end, long companyId, long scoupeGroupId, Locale locale, long userId) throws PortletException {
139			MessageUtility messageUtility = new MessageUtility(ScrivaniaCittadinoPortletKeys.BUNDLE_SYMBOLIC_NAME, locale);
140	
141			ComunicazioneDto dto = null;
142	
143			if(comunicazioneId > 0 && tipologiaComunicazione != null){
144				try{
145					switch (tipologiaComunicazione){
146						case COMUNICAZIONE:
147							dto = getComunicazione(comunicazioneId, start, end, companyId, scoupeGroupId, userId);
148							break;
149						case COMMENTO_DOMANDA_BANDO:
150							dto = getCommentoDomandaBando(comunicazioneId, messageUtility);
151							break;
152						case COMMENTO_RICHIESTA_SERVIZIO:
153							dto = getCommentoRichiesta(comunicazioneId, messageUtility);
154							break;
155						default:
156							throw new PortletException("TipologiaComunicazione non definita");
157					}
158	
159					hideBackOfficeName(dto,companyId, scoupeGroupId);
160	
161				}catch(PortalException portalException){
162					throw new PortletException(portalException);
163				}
164			}
165	
166			return dto;
