169		private ComunicazioneDto getComunicazione(long comunicazioneId, int start, int end, long companyId, long scoupeGroupId, long userId) throws PortletException {
170			ComunicazioneDto comunicazioneDto = null;
171			try {
172				Comunicazione comunicazione = comunicazioneLocalService.getComunicazione(comunicazioneId);
173	
174				if(comunicazione != null){
175					comunicazioneDto = mapComunicazione(comunicazione, start, end, companyId, scoupeGroupId, userId);
176				}
177			} catch (PortalException e) {
178				throw new PortletException(e);
179			}
180	
181			return comunicazioneDto;
182		}
183	
184		private ComunicazioneDto getCommentoDomandaBando(long commentoId, MessageUtility messageUtility) throws PortletException {
185			ComunicazioneDto commentoDto = null;
186	
187			try {
188				CommentoDomandaBando commentoDomandaBando = commentoDomandaBandoLocalService.getCommentoDomandaBando(commentoId);
189				if(commentoDomandaBando != null){
190					commentoDto = new ComunicazioneDto();
191					commentoDto.setCreateDate(commentoDomandaBando.getCreateDate());
