	 *
	 * @param serviceContext il contesto del servizio Liferay contenente scope e utente corrente
	 * @return la lista dei servizi ente attivi, {@code null} in caso di errore
	 */
	public List<ServizioEnte> getServiziEnte(ServiceContext serviceContext) {
		try {

			List<ServizioEnte> serviziEnte = servizioEnteLocalService.getServiziEnteByOrganizationIdSubOrganizationIdsAttivo(
					organizationUtility.getSiteOrganization(serviceContext.getScopeGroupId()).getOrganizationId(), getUserSubOrganizationIds(serviceContext), true, serviceContext.getScopeGroupId(),
					serviceContext.getCompanyId());

			return serviziEnte;
		}
		catch (PortalException e) {
			log.error("getServiziEnte :: " + e.getMessage(), e);
		}

		return null;
	}

