@Component(immediate = true, name = "PortletBandiSecurityService", service = PortletBandiSecurityService.class)
public class PortletBandiSecurityService {

	private static final String TEST_BANDI_ROLE_KEY = "test-bandi";

	private static final Log log = LogFactoryUtil.getLog(PortletBandiSecurityService.class.getName());

	@Reference
	private BandoLocalService bandoLocalService;

	@Reference
	private GroupLocalService groupLocalService;

	@Reference
	private RoleLocalService roleLocalService;

	/**
	 * Verifica che sia possibile accedere alla pagina (contenente la portlet) sulla base delle
	 * configurazione del bando corrispondente.
	 *
	 * @param request
	 * @throws PortletSecurityException
	 */
	public void checkServicePageAccess(RenderRequest request) throws PortletSecurityException {
		checkServicePageAccess(request, false);
	}

	public void checkServicePageAccess(RenderRequest request, boolean bypassBandoDisattivato) throws PortletSecurityException {
		ThemeDisplay themeDisplay = (ThemeDisplay) request.getAttribute(WebKeys.THEME_DISPLAY);

		PortletConfig portletConfig = (PortletConfig) request.getAttribute(JavaConstants.JAVAX_PORTLET_CONFIG);
		LiferayPortletConfig liferayPortletConfig = (LiferayPortletConfig) portletConfig;
		SessionMessages.add(request, liferayPortletConfig.getPortletId() + SessionMessages.KEY_SUFFIX_HIDE_DEFAULT_SUCCESS_MESSAGE);

		Layout layout = themeDisplay.getLayout();

		long layoutId = layout.getLayoutId();

		boolean isUserSignedIn = themeDisplay.isSignedIn();

		if (isUserSignedIn) {
			User user = themeDisplay.getUser();
			List<Role> userRoles = roleLocalService.getUserRoles(user.getUserId());
			if (userRoles != null) {
				for (Role role : userRoles) {
					if (role.getName().equals(TEST_BANDI_ROLE_KEY)) {
						return;
					}
				}
			}
		}

		Bando bando = bandoLocalService.findBandoByLayoutId(layoutId);

		if (bando == null) {
			log.debug("Bando non trovato :: layoutId: " + layoutId);
			throw new PortletSecurityException("Bando non trovato :: layoutId: " + layoutId);
		}

		// Controllo accesso a bando per data attivazione
		Date dataInizioAttivazione = bando.getDataInizio();
		Date dataFineAttivazione = bando.getDataFine();

		if (!bypassBandoDisattivato) {
			Date now = new Date();
			boolean isBandoAccessible = true;
			if(dataInizioAttivazione != null) {
				if (!(now.compareTo(dataInizioAttivazione) >= 0)) {
					isBandoAccessible = false;
				}
			} 
			if(dataFineAttivazione != null) {
				if (!(now.compareTo(dataFineAttivazione) <= 0)) {
					isBandoAccessible = false;
				}
			}

			if (!isBandoAccessible) {
				throw new PortletSecurityException("Bando " + bando.getNome() + " non attivo");
			}
		}

	}

}

