		try {
			serviceContext = ServiceContextFactory.getInstance(resourceRequest);
			themeDisplay = serviceContext.getThemeDisplay();
			serviziDigitaliCommonConfiguration = configurationProvider.getGroupConfiguration(ServiziDigitaliCommonConfiguration.class, themeDisplay.getScopeGroupId());
			User loggedUser = themeDisplay.getUser();
			int richiesteCount = 0;

			if(serviziDigitaliCommonConfiguration.recuperoInformazioniGenericheScrivanie()) {
				listaRichiestaFinal = scrivaniaCittadinoMiddlewareService.getRichiesteUtente(loggedUser.getScreenName(), filterOggettoNoteRichieste, filterIdRichiesta, filterStatoRichieste,
