				listaRichiestaFinal = scrivaniaCittadinoMiddlewareService.getRichiesteUtente(loggedUser.getScreenName(), filterOggettoNoteRichieste, filterIdRichiesta, filterStatoRichieste,
						themeDisplay.getSiteGroup().getCompanyId(), themeDisplay.getSiteGroup().getGroupId(), cur, ScrivaniaCittadinoPortletKeys.DEFAULT_DELTA, sortName, sortType,
						themeDisplay.getLocale(), serviziDigitaliCommonConfiguration.recuperoInformazioniGenericheScrivanie());

				richiesteCount = (int) scrivaniaCittadinoMiddlewareService.countRichiesteUtente(loggedUser.getScreenName(), filterOggettoNoteRichieste, filterStatoRichieste,
						themeDisplay.getSiteGroup().getCompanyId(), themeDisplay.getSiteGroup().getGroupId());
			}


			int numeroPagine = (int) Math.ceil((float) richiesteCount / ScrivaniaCittadinoPortletKeys.DEFAULT_DELTA);

			if (cur < numeroPagine) {
				hasNext = true;
			}
		}
		catch (Exception e) {
			auditService.saveErrorLog(resourceRequest, e.getMessage());
			_log.error("doServeResource() :: " + e.getMessage(), e);
			throw new Exception(e);
		}

		responseMap.put("listaRichieste", listaRichiestaFinal);
		responseMap.put("hasNext", hasNext);
		responseMap.put("cur", cur);

		String jsonObject = JSONFactoryUtil.looseSerializeDeep(responseMap);
		resourceResponse.getWriter().write(jsonObject);
	}

	@Reference
	protected void setConfigurationProvider(ConfigurationProvider configurationProvider) {
		this.configurationProvider = configurationProvider;
	}
