17	/**
18	 * Porta nel contesto FTL del tema le variabili necessarie allo switch del profilo attivo.
19	 *
20	 * <p>
21	 * Variabili esposte:
22	 * </p>
23	 * <ul>
24	 * <li>{@code activeRole} - "OPERATORE", "CITTADINO" o "".</li>
25	 * <li>{@code hasDualRole} - true se l'utente possiede entrambi i profili.</li>
26	 * <li>{@code switchProfiloUrl} - URL per lo switch al profilo opposto (vuoto se non doppio ruolo).</li>
27	 * <li>{@code switchProfiloLabel} - "Passa a Cittadino" / "Passa a Operatore" (vuoto se non doppio ruolo).</li>
28	 * </ul>
29	 *
30	 * <p>
31	 * Le guardie FTL ({@code activeRole??}, {@code hasDualRole??}) garantiscono che, se questo
32	 * contributor non è deployato, il tema si comporti esattamente come oggi.
33	 * </p>
34	 */
35	@Component(immediate = true, //
36			property = { "type=" + TemplateContextContributor.TYPE_THEME }, //
37			service = TemplateContextContributor.class//
38	)
39	public class ActiveRoleTemplateContextContributor implements TemplateContextContributor {
40	
41		@Override
42		public void prepare(Map<String, Object> contextObjects, HttpServletRequest request) {
43			String activeRole = "";
44			boolean hasDualRole = false;
45	
46			HttpSession session = request.getSession(false);
47			if (session != null) {
48				Object activeRoleAttr = session.getAttribute(ServiziDigitaliPortalConstants.ACTIVE_ROLE);
49				if (activeRoleAttr != null) {
50					activeRole = String.valueOf(activeRoleAttr);
51				}
52	
53				Object hasDualRoleAttr = session.getAttribute(ServiziDigitaliPortalConstants.HAS_DUAL_ROLE);
54				if (hasDualRoleAttr instanceof Boolean) {
55					hasDualRole = (Boolean) hasDualRoleAttr;
56				}
57			}
58	
59			String switchProfiloUrl = "";
60			String switchProfiloLabel = "";
61	
62			if (hasDualRole && Validator.isNotNull(activeRole)) {
63				boolean operatoreAttivo = ServiziDigitaliPortalConstants.ROLE_OPERATORE.equals(activeRole);
64				String targetRole = operatoreAttivo ? ServiziDigitaliPortalConstants.ROLE_CITTADINO : ServiziDigitaliPortalConstants.ROLE_OPERATORE;
65				switchProfiloUrl = buildSwitchUrl(request, targetRole);
66				switchProfiloLabel = operatoreAttivo ? "Passa a Cittadino" : "Passa a Operatore";
67			}
68	
69			contextObjects.put("activeRole", activeRole);
70			contextObjects.put("hasDualRole", hasDualRole);
71			contextObjects.put("switchProfiloUrl", switchProfiloUrl);
72			contextObjects.put("switchProfiloLabel", switchProfiloLabel);
73		}
74	
75		/**
76		 * Costruisce l'URL di switch verso il profilo opposto: home del sito corrente con il parametro
77		 * {@link ServiziDigitaliPortalConstants#ROLE_SWITCH_PARAM}, intercettato da {@code RoleSwitchFilter}.
78		 *
79		 * @return l'URL di switch, oppure stringa vuota se il {@code ThemeDisplay} non è disponibile
80		 */
81		private String buildSwitchUrl(HttpServletRequest request, String targetRole) {
82			ThemeDisplay themeDisplay = (ThemeDisplay) request.getAttribute(WebKeys.THEME_DISPLAY);
83			if (themeDisplay == null) {
84				return "";
85			}
86	
87			return themeDisplay.getURLHome() + "?" + ServiziDigitaliPortalConstants.ROLE_SWITCH_PARAM + "=" + targetRole;
88		}
89	}
